-- 99_item_reference_repairs.sql -- item reference repairs, DB step 38.
--
-- GENERATED by Custom/Documentation/scripts/gen_item_reference_repairs.py.
--
-- ============================================================================
-- 1. 114 items losing their icon every boot -- the BIG one, and NOT from the
--    map-751 import. These are DC custom items, entries 52199-59520.
--
--    The log line reads
--      Item (Entry: 52199) does not have a correct display id (800047), must be 0.
--    which looks like a missing display. It is not. The core check is
--      ObjectMgr.cpp:3534  if (itemTemplate.DisplayInfoID != dbcitem->DisplayInfoID)
--    -- item_template disagreeing with **Item.dbc** -- and the core then
--    OVERWRITES item_template with the DBC value. "must be 0" = the DBC side
--    reads 0, so the icon is stripped at every startup.
--
--    Where the 0 comes from: `item_dbc` is a runtime overlay merged OVER the
--    binary Item.dbc at load, and 114 of its rows carry DisplayInfoID = 0
--    while BOTH item_template and the shipped Item.dbc carry the real 800xxx
--    value. The overlay is the outlier and it wins.
--
--    Verified before choosing a direction: all 114 exist in Item.dbc with a
--    non-zero display; every one of those displays exists in ItemDisplayInfo;
--    and DisplayInfoID is the ONLY column that disagrees -- ClassID,
--    SubclassID, Sound_Override_Subclassid, Material, InventoryType and
--    SheatheType match on every row. Hence a one-column sync.
-- ============================================================================

UPDATE `item_dbc` d
JOIN `item_template` i ON i.`entry` = d.`ID`
SET d.`DisplayInfoID` = i.`displayid`
WHERE d.`DisplayInfoID` <> i.`displayid`;

-- ---------------------------------------------------------------------------
-- 2. PageText
--    3745 exists in cata_world and chains 3745->3746->3747->3748->3749->0,
--    so the whole chain comes across for item 64666. page_text has the same
--    four columns on both sides, so this is a straight copy.
-- ---------------------------------------------------------------------------
DELETE FROM `page_text` WHERE `ID` IN (3745,3746,3747,3748,3749);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `VerifiedBuild`)
SELECT `ID`, `Text`, `NextPageID`, `VerifiedBuild` FROM `cata_world`.`page_text` WHERE `ID` IN (3745,3746,3747,3748,3749);

--    3708, 3718 and 3722 are in NO source we have -- not our page_text, not
--    cata_world. Nothing to import, so the reference is dropped: the item
--    keeps working, it just has no readable page.
UPDATE `item_template` SET `PageText` = 0 WHERE `entry` = 60977 AND `PageText` = 3708;
UPDATE `item_template` SET `PageText` = 0 WHERE `entry` = 62932 AND `PageText` = 3718;
UPDATE `item_template` SET `PageText` = 0 WHERE `entry` = 63249 AND `PageText` = 3722;

-- ---------------------------------------------------------------------------
-- 3. RequiredReputationFaction 1168 = Cataclysm's GUILD reputation
--    Confirmed from the Cata client's own Faction.dbc, whose description for
--    1168 reads "Guild reputation is your personal standing with your guild".
--    3.3.5 has no guild reputation, so this requirement is unenforceable, not
--    merely missing -- there is no rank a player could ever reach. Zeroed.
--    (The six are the Cata guild banners: Banner of Cooperation, Standard of
--    Unity, Battle Standard of Coordination, x2 each.)
-- ---------------------------------------------------------------------------
UPDATE `item_template` SET `RequiredReputationFaction` = 0, `RequiredReputationRank` = 0
WHERE `entry` IN (63359,64398,64399,64400,64401,64402) AND `RequiredReputationFaction` = 1168;

-- ---------------------------------------------------------------------------
-- 4. Item 68647 spellid_1 = 96022 -- NOT fixed here.
--    96022 is "Dousing Agent" and IS present in the Cata 4.3.4 client, so it
--    is downported by 88_ (now 231 spells) rather than stripped. Re-apply 88_.
--
-- 5. Bag family bit 15 -- NOT fixed here either, it is a DBC row.
--    BagFamily 32768 = bit 15, and the core looks up ItemBagFamily id bit+1 =
--    16. Our ItemBagFamily has ids 0-15; Cata has 0-16. Rather than strip the
--    bit off the five items that carry it (Stag Eye, Severed Abomination Head,
--    Giant Flesh-Eating Tadpole, Corpse Worm, Corpse-Fed Pike -- all cooking /
--    fishing ingredients), row 16 is added to ItemBagFamily from the Cata
--    client. That keeps the items' intent and also fixes 58949, which is
--    pre-existing. Note BagFamily 4096 = bit 12 -> id 13 is VALID and its 179
--    items were never in error.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 5b. ItemBagFamily id 16 -- the overlay half of the DBC row.
--     Cata's own name for family 16 is "Fishing Supplies", which is exactly what
--     the five items carrying bit 15 are (Stag Eye, Corpse Worm, Corpse-Fed Pike,
--     Giant Flesh-Eating Tadpole, Severed Abomination Head).
--     The Cata row could NOT be copied verbatim: Cata collapsed the locale block to
--     2 fields / 8 bytes where 3.3.5 has 18 / 72, so the row is rebuilt in our shape
--     -- name in the enUS slot only and mask 16711934, matching every existing row.
-- ---------------------------------------------------------------------------
DELETE FROM `itembagfamily_dbc` WHERE `ID` = 16;
INSERT INTO `itembagfamily_dbc` (`ID`, `Name_Lang_enUS`, `Name_Lang_Mask`) VALUES (16, 'Fishing Supplies', 16711934);

-- ---------------------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------------------
SELECT 'item_dbc rows still disagreeing on display (want 0)' AS what, COUNT(*) AS n
  FROM `item_dbc` d JOIN `item_template` i ON i.`entry` = d.`ID` WHERE d.`DisplayInfoID` <> i.`displayid`
UNION ALL SELECT 'page_text chain imported (want 5)', COUNT(*)
  FROM `page_text` WHERE `ID` IN (3745,3746,3747,3748,3749)
UNION ALL SELECT 'items whose PageText points nowhere (want 0)', COUNT(*)
  FROM `item_template` i WHERE i.`PageText` > 0
    AND NOT EXISTS (SELECT 1 FROM `page_text` p WHERE p.`ID` = i.`PageText`)
UNION ALL SELECT 'items still requiring faction 1168 (want 0)', COUNT(*)
  FROM `item_template` WHERE `RequiredReputationFaction` = 1168
UNION ALL SELECT 'ItemBagFamily 16 present (want 1)', COUNT(*)
  FROM `itembagfamily_dbc` WHERE `ID` = 16;

-- must be empty: an item whose display, after the sync, is not in the shipped
-- ItemDisplayInfo overlay AND not zero
SELECT 'PROBLEM: synced display missing' AS problem, d.`ID`, d.`DisplayInfoID`
FROM `item_dbc` d WHERE d.`DisplayInfoID` > 0
  AND NOT EXISTS (SELECT 1 FROM `itemdisplayinfo_dbc` x WHERE x.`ID` = d.`DisplayInfoID`)
  AND d.`DisplayInfoID` NOT BETWEEN 1 AND 799999;
